pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    address alice = address(0x1234);

    function setUp() public { 
        c = new XBORNID(); 
    }

    function testRegression_property() public {
        assertFalse(c.blacklist(alice));

        vm.deal(alice, 10 ether);

        vm.prank(alice);
        c.getTokens{value: 1 ether}();

        uint256 balanceAfterFirst = address(c).balance;

        uint256 valueAfterFirst = c.value();

        assertTrue(valueAfterFirst < 1000e18, "Reference should have decreased value");
    }
}
